#!/usr/bin/env python3

"""Build, approve and check the modernization assessment (gate 1) and plan (gate 2).



build:          merge the tool evidence (facts.json, facts.md) with the structured findings that the

                two analyst agents posted on the issue. Write findings.json and assessment.md, post the

                report on the issue, and add it to the job summary.

approve:        record who approved the report and print the approver's login.

validate-plan:  check that a plan covers every finding ID and has the required sections.



Usage:

  modernize_assessment.py build --issue 12 --facts facts --out out [--usage usage-artifacts]

  modernize_assessment.py approve --issue 12

  modernize_assessment.py validate-plan --findings findings.json --plan plan.md --out validation.md

Requires GH_TOKEN, GITHUB_REPOSITORY and GITHUB_RUN_ID for build and approve.

"""

import argparse

import json

import os

import pathlib

import re

import subprocess

import sys



sys.path.insert(0, str(pathlib.Path(__file__).parent))

import modernize_cost  # noqa: E402

import modernize_facts  # noqa: E402



MARKER = "<!-- modernize-assessment -->"

ANALYSTS = [

    ("modernize-compat-analyst", "Source compatibility", "C"),

    ("modernize-dependency-analyst", "Dependencies and build tooling", "D"),

]

RANKS = ["Blocker", "Change", "Watch", "No change"]

COMMENT_LIMIT = 60000

PLAN_SECTIONS = ["Request", "Run Parameters", "Assessment Summary", "Scope", "Execution Plan", "Finding Coverage", "Validation", "Risks and Rollback", "Cost Estimate", "Approval Checklist"]





def gh(*args, stdin=None, check=True):

    result = subprocess.run(["gh", *args], input=stdin, capture_output=True, text=True, encoding="utf-8")

    if result.returncode != 0:

        if check:

            sys.exit(f"gh {' '.join(args)} failed: {result.stderr.strip()}")

        return None

    return result.stdout





def list_comments(repo, number):

    out = gh("api", f"repos/{repo}/issues/{number}/comments", "--paginate", "--jq", ".[] | {id, body, html_url}")

    return [json.loads(line) for line in out.splitlines() if line.strip()]





def find_analyst_comment(comments, workflow_id, run_id):

    # gh-aw removes HTML comments from agent output, so match the footer it adds itself.

    footer = f"gh-aw-agentic-workflow: {workflow_id},"

    mine = [c for c in comments if footer in c["body"]]

    this_run = [c for c in mine if f"id: {run_id}," in c["body"]]

    chosen = this_run or mine

    return max(chosen, key=lambda c: c["id"]) if chosen else None





def extract_structured(body):

    """Return the JSON object with a 'findings' list from the comment's fenced json blocks."""

    for block in re.findall(r"```json\s*\n(.*?)\n```", body, flags=re.S):

        try:

            data = json.loads(block)

        except ValueError:

            continue

        if isinstance(data, dict) and isinstance(data.get("findings"), list):

            return data

    return None





def human_part(body):

    """The analyst comment without its JSON block and the gh-aw footer."""

    body = re.sub(r"```json\s*\n.*?\n```", "", body, flags=re.S)

    keep = [line for line in body.splitlines() if not line.startswith("> Generated by") and not line.startswith("<!-- gh-aw-")]

    return "\n".join(keep).strip()





def normalize(findings, prefix, analyst):

    result = []

    for index, item in enumerate(findings, 1):

        rank = str(item.get("rank", "Watch")).strip().title()

        rank = "No change" if rank.lower().startswith("no") else rank

        result.append({

            "id": f"{prefix}-{index:02d}",

            "analyst": analyst,

            "rank": rank if rank in RANKS else "Watch",

            "module": item.get("module") or "",

            "path": (item.get("path") or "").removeprefix("./"),

            "line": item.get("line") if isinstance(item.get("line"), int) else None,

            "category": item.get("category") or "",

            "finding": item.get("finding") or "",

            "change": item.get("change") or "",

            "owner": item.get("owner") or "",

            "evidence": item.get("evidence") or "",

            "confidence": item.get("confidence") or "",

            "artifact": item.get("artifact"),

            "current": item.get("current"),

            "target": item.get("target"),

            "decision": item.get("decision"),

        })

    return result





def P(count, word, many=None):

    """Count with the right singular or plural noun."""

    return f"{count} {word}" if count == 1 else f"{count} {many or word + 's'}"





def cell(value):

    return str(value or "").replace("|", "/").replace("\n", " ").strip()





def where(facts, f):

    if f["path"]:

        return modernize_facts.link(facts, f["path"], f["line"])

    return f"`{f['artifact']}`" if f.get("artifact") else ""





def mermaid_pie(title, counts):

    data = [(k, v) for k, v in counts.items() if v]

    if not data:

        return []

    # Mermaid labels slices with percentages and, with showData, the legend with counts. Name the total.

    title = f"{title}, {sum(v for _, v in data)} total"

    return ["```mermaid", f"pie showData title {title}"] + [f'    "{k}" : {v}' for k, v in data] + ["```", "",

            "_Slices show the share of the total; the legend shows the count._", ""]





def predicted_row(predicted):
    if not predicted:
        return "| GitHub Actions minutes | n/a | | not predicted |"
    stages = predicted["stages"].values()
    minutes = sum(s["minutes"] or 0 for s in stages)
    usd = modernize_cost.runner_usd(minutes, predicted.get("private"), predicted["rate"])
    return f"| GitHub Actions minutes, all stages | {minutes} runner minutes | {usd} | job history or baseline |"


def render(facts, findings, structured, sections, issue, run_url, estimate_md, estimate_total, actual_md, full=True, summaries=True,
           predicted=None, predicted_md=None):

    b = facts["build"]

    base = facts["baseline"]["totals"]

    inv = {m["module"]: m for m in facts["inventory"]}

    by_rank = {r: sum(1 for f in findings if f["rank"] == r) for r in RANKS}

    by_module = {}

    for f in findings:

        by_module[f["module"] or "parent"] = by_module.get(f["module"] or "parent", 0) + 1

    osv = facts["vulnerabilities"]

    target_boot = facts["targets"]["spring_boot_3_5_latest"] or "3.5.x"

    jakarta = [r for r in facts["javax"] if r["action"] == "jakarta"]

    preview = facts["preview"]



    lines = [MARKER, f"# Assessment report for issue {issue}", "",

             "Status: waiting for your approval (gate 1). Read the report, then approve at the end of this page.", "",

             "No file in the repository has changed. Approving this report starts the planner agent, which opens the plan pull request (gate 2). Code changes only start after a human merges that plan.", ""]



    lines += ["## At a glance", "",

              "```mermaid", "flowchart LR",

              f'    R["Request<br/>issue {issue}"] --> T["Tools measure<br/>tests, Maven, jdeps, OpenRewrite, OSV"]',

              '    T --> A["2 analyst agents<br/>read-only"]',

              f'    A --> G1{{"Gate 1<br/>this report<br/>{len(findings)} findings"}}',

              '    G1 -- "approve" --> P["Planner agent<br/>plan pull request"]',

              '    P --> G2{"Gate 2<br/>merge the plan"}',

              '    G2 --> X["Agents change code<br/>on a branch"]',

              '    X --> G3{"Gate 3<br/>review the PR"}',

              "    style G1 fill:#fff3cd,stroke:#d4a106", "```", "",

              "| Measure | Now | Target or result | Source |", "|---|---|---|---|",

              f"| Java | {b['java_version']} | 21 | `{b['pom_path']}` |",

              f"| Spring Boot | {b['spring_boot_version']} | {target_boot} (latest 3.5.x) | Maven Central |",

              f"| Maven Wrapper | {b['maven_wrapper']} | {facts['targets']['maven_3_9_latest'] or '3.9.x'} or keep | `{b['wrapper_path']}` |",

              f"| Code | {sum(m['main_files'] for m in facts['inventory'])} classes, {sum(m['main_loc'] for m in facts['inventory'])} lines | | source scan |",

              f"| Tests on JDK 8 | {base['tests']} run, {base['failures']} failed, {P(base['errors'], 'error')} | no worse after upgrade | `mvnw test` |",

              f"| `javax` imports to migrate | {len(jakarta)} in {len({r['path'] for r in jakarta})} files | 0 | source scan |",

              f"| JDK internal API use | {len(facts['jdk21']['internal_api'])} dependencies | resolved by newer versions | `jdeps` |",

              f"| Known vulnerabilities | {len(osv.get('items', [])) if osv.get('available') else 'n/a'} advisories | re-scanned after upgrade | OSV.dev |",

              f"| Static analysis | {len(facts.get('spotbugs', {}).get('items', [])) if facts.get('spotbugs', {}).get('available') else 'n/a'} bug patterns | no new ones after upgrade | SpotBugs |",

              f"| Preview of the change | {len(preview['files'])} files | reference only | OpenRewrite dry run |",

              f"| Findings | {', '.join(f'{v} {k.lower()}' for k, v in by_rank.items() if v) or 'none'} | each one owned by a plan step | analyst agents |",

              f"| Estimated AI cost of plan and execution | {modernize_cost.fmt_credits(estimate_total)} credits | {modernize_cost.fmt_usd(estimate_total)} | measured profile |",
              predicted_row(predicted), ""]



    # show-me: what the requested upgrade changes, as a diff sketch, and where, as a file tree.

    keep = [r for r in facts["javax"] if r["action"] == "keep"]

    lines += ["What the requested upgrade changes. Nothing is changed yet:", "", "```diff", " asset-manager/",

              f"-  java.version                  {b['java_version']}", "+  java.version                  21",

              f"-  spring-boot-starter-parent    {b['spring_boot_version']}", f"+  spring-boot-starter-parent    {target_boot}",

              f"-  javax.* imports               {len(jakarta)} in {len({r['path'] for r in jakarta})} files", "+  jakarta.* imports"]

    if keep:

        lines.append(f"   {', '.join(sorted({r['package'] for r in keep}))}{' ' * 4}stays, it ships with the JDK")

    lines += ["```", ""]

    if preview["files"]:

        lines += ["Files the OpenRewrite preview touches:", "", "```text", "asset-manager/"]

        files = [f["path"] for f in preview["files"]]

        for i, path in enumerate(files):

            branch = "└──" if i == len(files) - 1 else "├──"

            stats = next(f for f in preview["files"] if f["path"] == path)

            lines.append(f"{branch} {path:<88} +{stats['added']} -{stats['removed']}")

        lines += ["```", ""]



    lines += ["```mermaid", "flowchart TB",

              f'    PARENT["asset-manager (parent POM)<br/>Java {b["java_version"]}, Spring Boot {b["spring_boot_version"]}<br/>{P(by_module.get("parent", 0), "finding")}"]']

    for name, m in inv.items():

        node = re.sub(r"\W", "", name).upper()

        lines.append(f'    PARENT --> {node}["{name}<br/>{m["main_files"]} classes, {m["main_loc"]} lines<br/>{P(m["test_files"], "test class", "test classes")}<br/>{P(by_module.get(name, 0), "finding")}"]')

        if m["test_files"] == 0:

            lines.append(f"    style {node} stroke:#d93f0b,stroke-width:2px")

    lines += ["```", ""]

    lines += mermaid_pie("Findings by rank", by_rank)

    if osv.get("available") and osv.get("items"):

        lines += mermaid_pie("Known advisories by severity (before)", modernize_facts.severity_counts(osv["items"]))



    decisions = []

    for analyst, data in structured.items():

        for d in (data or {}).get("decisions", []) or []:

            decisions.append(f"- [ ] {cell(d.get('question'))} Recommended: {cell(d.get('recommendation'))}. {cell(d.get('why'))} ({analyst})")

    if not any(m["test_files"] for m in facts["inventory"] if m["module"] == "web"):

        decisions.append("- [ ] The `web` module has no tests, so the pipeline cannot prove its behavior is unchanged. Accept this, or ask for tests in a separate request.")

    failing = [c for c in facts["baseline"]["cases"] if c["status"] in ("failed", "error")]

    for c in failing:

        decisions.append(f"- [ ] `{c['class'].split('.')[-1]}.{c['name']}` already fails on JDK 8 ({cell(c['message'])[:120]}). The code fixer must fix it if the upgrade allows, or explain why not.")

    decisions.append(f"- [ ] Target Spring Boot {target_boot}. Newer major versions (4.x) are out of the approved scope.")

    lines += ["## Decisions for the reviewer", "", "Check these before you approve. Each one becomes a constraint in the plan.", ""] + decisions + [""]



    lines += ["## Findings", "", "Each finding has a stable ID. The plan assigns every ID to a step, commits reference the IDs they address, and the review checks each one.", "",

              "| ID | Rank | Module | Where | Finding | Proposed change | Owner | Confidence |", "|---|---|---|---|---|---|---|---|"]

    for f in sorted(findings, key=lambda x: (RANKS.index(x["rank"]), x["id"])):

        lines.append(f"| {f['id']} | {f['rank']} | {cell(f['module'])} | {where(facts, f)} | {cell(f['finding'])} | {cell(f['change'])} | `{cell(f['owner'])}` | {cell(f['confidence'])} |")

    if not findings:

        lines.append("| | | | | No structured findings were posted. Read the analyst comments below. | | | |")

    lines.append("")



    deps = [f for f in findings if f.get("artifact")]

    if deps:

        lines += ["### Dependency decisions", "", "| ID | Artifact | Current | Decision | Target | Why |", "|---|---|---|---|---|---|"]

        for f in deps:

            lines.append(f"| {f['id']} | `{cell(f['artifact'])}` | {cell(f['current'])} | {cell(f['decision'])} | {cell(f['target'])} | {cell(f['finding'])} |")

        lines.append("")



    lines += ["## Analyst summaries", ""]

    for (workflow_id, title, _), summary in zip(ANALYSTS, sections):

        link = f"[Original comment]({summary['url']})" if summary.get("url") else ""

        if summaries:

            lines += ["<details>", f"<summary>{title}, from <code>{workflow_id}</code></summary>", "", summary["text"] or "_No comment found._", "",

                      link, "", "</details>", ""]

        else:

            lines += [f"- {title}, from `{workflow_id}`: {link or 'no comment found'}"]

    lines.append("")



    if full:

        lines += [modernize_facts.render_markdown(facts, facts.get("_raw")).replace("## Evidence measured by tools", "## Evidence measured by tools (no AI)", 1)]

    else:

        lines += ["## Evidence measured by tools (no AI)", "", f"The full evidence is in the [run summary]({run_url}) and the `assessment` artifact. "

                  "After approval it is committed with the plan as `assessment.md` and `evidence/`.", ""]



    lines += ["## After you approve", "",

              "| Step | Who | Changes | Human gate |", "|---|---|---|---|",

              "| Plan | `modernize-planner` agent | Opens a pull request with `plan.md`, this report and the evidence. No code. | Gate 2: merge the plan |",

              "| Build upgrade | `modernize-build-upgrader` agent | POM files and Maven Wrapper only | |",

              "| Code fixes | `modernize-code-fixer` agent | Java sources and tests, in a build and test loop | |",

              "| Verify | Actions jobs, no AI | JDK 21 build and tests against this baseline, version and namespace checks, OSV re-scan | |",

              "| Review | `modernize-conformance-reviewer` (spec) and `modernize-standards-reviewer` (standards), in parallel | Comments only | |",

              "| Result | Draft Implementation pull request | Branch `modernize/issue-" + str(issue) + "`, never `main` | Gate 3: review the PR |", ""]

    if predicted_md:
        lines += ["### Predicted cost of every stage (AI and GitHub Actions)", "", predicted_md,
                  "<details><summary>Estimated AI cost of the next stages, per agent</summary>", "", estimate_md, "</details>", ""]
    else:
        lines += ["### Estimated AI cost of the next stages", "", estimate_md]

    if actual_md:

        lines += ["### AI cost so far (this assessment run)", "", actual_md]

    lines += approve_section(run_url)

    return "\n".join(lines).rstrip() + "\n"





APPROVE_PREFIX = "**To approve:**"





def approve_section(run_url):

    return ["## Approve (gate 1)", "",

            f"{APPROVE_PREFIX} click [assessment run]({run_url}), then **Review deployments** → tick `assessment-review` → **Approve and deploy**. "

            "**Reject** stops here; nothing changes.", ""]





def mark_approved(body, text):

    """Replace the approve instruction at the end of the report once gate 1 is passed."""

    return re.sub(rf"(?m)^{re.escape(APPROVE_PREFIX)}.*$", lambda _: text, body, count=1)





def upsert_comment(repo, number, body):

    existing = next((c for c in list_comments(repo, number) if MARKER in c["body"]), None)

    if existing:

        gh("api", "-X", "PATCH", f"repos/{repo}/issues/comments/{existing['id']}", "-F", "body=@-", stdin=body)

    else:

        gh("api", "-X", "POST", f"repos/{repo}/issues/{number}/comments", "-F", "body=@-", stdin=body)





def build(args):

    repo, run_id = os.environ["GITHUB_REPOSITORY"], os.environ["GITHUB_RUN_ID"]

    run_url = f"{os.environ.get('GITHUB_SERVER_URL', 'https://github.com')}/{repo}/actions/runs/{run_id}"

    facts_dir = pathlib.Path(args.facts)

    facts = json.loads((facts_dir / "facts.json").read_text(encoding="utf-8"))

    facts["_raw"] = str(facts_dir / "raw")

    comments = list_comments(repo, args.issue)



    findings, structured, sections = [], {}, []

    for workflow_id, title, prefix in ANALYSTS:

        comment = find_analyst_comment(comments, workflow_id, run_id)

        if not comment:

            sys.exit(f"No comment from {workflow_id} on issue #{args.issue}. The assessment cannot be reviewed without it.")

        data = extract_structured(comment["body"])

        structured[workflow_id] = data

        if data:

            findings += normalize(data["findings"], prefix, workflow_id)

        else:

            print(f"::warning::{workflow_id} posted no structured findings block. Its comment is shown as text only.")

        sections.append({"text": human_part(comment["body"]), "url": comment.get("html_url")})



    rows = modernize_cost.estimate_rows(["plan", "execution"], args.workflows)

    estimate_md, estimate_total = modernize_cost.estimate_markdown(rows)

    actual_md = None

    if args.usage and pathlib.Path(args.usage).exists():

        usage = modernize_cost.read_usage(args.usage)

        actual_md = modernize_cost.actual_markdown(usage)[0] if usage else None

    predicted = modernize_cost.predict(repo, run_id, args.usage, facts, args.workflows)
    predicted_md = modernize_cost.render_estimate(predicted)



    out = pathlib.Path(args.out)

    out.mkdir(parents=True, exist_ok=True)

    doc = {"issue": int(args.issue), "commit": facts.get("commit"), "run": run_url, "findings": findings,

           "decisions": {k: (v or {}).get("decisions", []) for k, v in structured.items()}}

    (out / "findings.json").write_text(json.dumps(doc, indent=2), encoding="utf-8")
    (out / "cost-estimate.json").write_text(json.dumps(predicted, indent=2), encoding="utf-8")

    report = render(facts, findings, structured, sections, args.issue, run_url, estimate_md, estimate_total, actual_md, full=True,
                    predicted=predicted, predicted_md=predicted_md)

    (out / "assessment.md").write_text(report, encoding="utf-8")

    # GitHub rejects comments over 65,536 characters. Drop detail step by step until the comment fits.

    comment = report

    for full, summaries in ((False, True), (False, False)):

        if len(comment) <= COMMENT_LIMIT:

            break

        comment = render(facts, findings, structured, sections, args.issue, run_url, estimate_md, estimate_total, actual_md, full=full, summaries=summaries,
                         predicted=predicted, predicted_md=predicted_md)

    if len(comment) > COMMENT_LIMIT:

        note = f"\n\n_Truncated to fit a GitHub comment. The full report is in the [run summary]({run_url}) and the `assessment` artifact._\n"

        tail = "\n" + "\n".join(approve_section(run_url))

        comment = comment[: COMMENT_LIMIT - len(note) - len(tail)] + note + tail

    upsert_comment(repo, args.issue, comment)

    summary = os.environ.get("GITHUB_STEP_SUMMARY")

    if summary:

        with open(summary, "a", encoding="utf-8") as handle:

            handle.write(report.replace(MARKER, ""))

    print(f"assessment: {len(findings)} findings, report {len(report)} chars, comment {'full' if comment is report else 'condensed'}")





REQUEST_MARKER = "<!-- modernize-request -->"

# The organization's approved baseline. The pipeline enforces it; the developer does not need to know it.

BASELINE = {"java": "21", "java_label": "Java 21 (LTS)", "spring_boot": "3.5.x", "spring_boot_label": "Spring Boot 3.5.x (latest patch)"}





def expand_request(args):

    """Turn the developer's short /modernize request into the full request the pipeline will execute."""

    repo = os.environ["GITHUB_REPOSITORY"]

    issue = json.loads(gh("api", f"repos/{repo}/issues/{args.issue}", "--jq", "{body, user: .user.login}"))

    text = "\n".join(line for line in (issue["body"] or "").splitlines() if not line.strip().startswith("/modernize")).strip()

    build = modernize_facts.build_facts(pathlib.Path(args.project), pathlib.Path("."))

    boot = modernize_facts.maven_latest("org.springframework.boot", "spring-boot-starter-parent", r"3\.5\.\d+") or BASELINE["spring_boot"]

    modules = ", ".join(f"`{m['name']}`" for m in build["modules"])

    quoted = "\n".join(f"> {line}" if line.strip() else ">" for line in (text or "(no description)").splitlines())

    lines = [

        REQUEST_MARKER,

        "## Modernization request, expanded",

        "",

        f"@{issue['user']} asked:",

        "",

        quoted,

        "",

        "The pipeline expanded it into the request below. The current state is read from the repository, not assumed. Nothing changes until a human approves the assessment (gate 1) and merges the plan (gate 2).",

        "",

        "### Business outcome",

        "",

        f"Keep `{args.project}` on a supported runtime and framework so the team can keep developing and patching it, without changing what the application does.",

        "",

        "### Requested modernization",

        "",

        "| | Now (read from the build files) | Target (approved baseline) |",

        "|---|---|---|",

        f"| Java | {build['java_version']} (`{build['pom_path']}`) | {BASELINE['java_label']} |",

        f"| Spring Boot | {build['spring_boot_version']} (`{build['pom_path']}`) | {BASELINE['spring_boot_label']}, {boot} today |",

        f"| Build | Maven Wrapper {build['maven_wrapper']}, modules {modules} | same modules, Maven 3.9.x |",

        "| Behavior | as today | unchanged for web and worker |",

        "| Proof | baseline tests on the current JDK | build and tests on JDK 21 no worse than the baseline |",

        "",

        "```diff",

        f" {args.project}/",

        f"-  Java {build['java_version']}, Spring Boot {build['spring_boot_version']}",

        f"+  Java {BASELINE['java']}, Spring Boot {boot}",

        "   web and worker behavior    unchanged",

        "```",

        "",

        "### How this request is handled",

        "",

        "```mermaid",

        "flowchart LR",

        '    R["This issue"] --> A["Assess: tools measure, 2 agents find"]',

        '    A --> G1{"Gate 1: approve the assessment"}',

        '    G1 --> P["Plan: planner agent, plan PR"]',

        '    P --> G2{"Gate 2: merge the plan"}',

        '    G2 --> X["Execute: agents change code on a branch"]',

        '    X --> V["Verify: JDK 21 build, tests, scans"]',

        '    V --> G3{"Gate 3: review the Implementation PR"}',

        "    style R fill:#ffec99,stroke:#f08c00",

        "```",

        "",

        "1. Standard Java tools measure the application: tests, dependency tree, jdeps, SpotBugs, an OpenRewrite preview, known advisories. No AI.",

        "2. Two read-only agents turn the measurements into findings with IDs. One Assessment Report appears on this issue. **Gate 1:** a human approves it.",

        "3. A planner agent writes the plan into a pull request. **Gate 2:** a human merges it.",

        "4. Agents change the code on a branch, Actions jobs verify it, two reviewer agents check it. **Gate 3:** a human reviews the Implementation pull request.",

        "",

        "### Out of scope",

        "",

        "Azure service migration, containerization, deployment, CI/CD, observability, production rollout, and Spring Boot 4. "

        "The pipeline refuses steps that touch them.",

        "",

        "### What you do next",

        "",

        "Nothing until the **Assessment report** comment appears here, in about 10 to 15 minutes. The **Modernization status** comment below tracks every stage.",

    ]

    body = "\n".join(lines) + "\n"

    existing = next((c for c in list_comments(repo, args.issue) if REQUEST_MARKER in c["body"]), None)

    if existing:

        gh("api", "-X", "PATCH", f"repos/{repo}/issues/comments/{existing['id']}", "-F", "body=@-", stdin=body)

    else:

        gh("api", "-X", "POST", f"repos/{repo}/issues/{args.issue}/comments", "-F", "body=@-", stdin=body)

    print(f"expanded request: Java {build['java_version']} -> {BASELINE['java']}, Spring Boot {build['spring_boot_version']} -> {boot}")





def find_approver(repo, run_id):

    out = gh("api", f"repos/{repo}/actions/runs/{run_id}/approvals", check=False)

    try:

        approvals = [a for a in json.loads(out or "[]") if a.get("state") == "approved"]

        return approvals[-1]["user"]["login"]

    except (ValueError, KeyError, IndexError, TypeError):

        return None





def approve(args):

    repo, run_id = os.environ["GITHUB_REPOSITORY"], os.environ["GITHUB_RUN_ID"]

    approver = find_approver(repo, run_id)

    who = f"@{approver}" if approver else "a required reviewer"

    comment = next((c for c in list_comments(repo, args.issue) if MARKER in c["body"]), None)

    if not comment:

        sys.exit(f"No assessment report comment on issue #{args.issue}.")

    status = f"Status: approved by {who}. The planner agent is writing the plan pull request (gate 2)."

    body = re.sub(r"(?m)^Status:.*$", status, comment["body"], count=1)

    run_url = f"{os.environ.get('GITHUB_SERVER_URL', 'https://github.com')}/{repo}/actions/runs/{run_id}"
    body = mark_approved(body, f"Approved by {who} in the [assessment run]({run_url}). The plan pull request is next (gate 2).")

    gh("api", "-X", "PATCH", f"repos/{repo}/issues/comments/{comment['id']}", "-F", "body=@-", stdin=body)

    print(approver or "a required reviewer")





def stamp(args):

    """Record the gate 1 approval in the committed copy of the report and in findings.json."""

    report = pathlib.Path(args.report)

    text = report.read_text(encoding="utf-8").replace(MARKER + "\n", "", 1)

    status = (f"Status: approved by @{args.approver} on {args.approved_at} (gate 1). Assessed commit `{args.sha[:12]}`. "

              f"The approval is recorded in the [assessment run]({args.run}). This file is the approved record; do not edit it.")

    text = re.sub(r"(?m)^Status:.*$", lambda _: status, text, count=1)

    text = mark_approved(text, f"Approved by @{args.approver} on {args.approved_at} in the [assessment run]({args.run}).")

    text = re.sub(r"(?m)^No file in the repository has changed\. Approving this report.*$",

                  "No file in the repository changed before this approval. The plan in this folder was written from this report.", text, count=1)

    notes = json.loads(pathlib.Path(args.notes).read_text(encoding="utf-8")) if args.notes and pathlib.Path(args.notes).exists() else []

    if notes:

        block = ["## Reviewer notes at gate 1", "",

                 "Written by humans on the request issue before the approval. They are part of the approved record. The plan must answer each one.", ""]

        for note in notes:

            block += [f"### Note from @{note['author']} ({note['created_at']})", "", note["body"].strip(), ""]

        text = text.replace("## At a glance", "\n".join(block) + "\n## At a glance", 1)

    report.write_text(text, encoding="utf-8")

    findings = pathlib.Path(args.findings)

    doc = json.loads(findings.read_text(encoding="utf-8"))

    doc["approval"] = {"approver": args.approver, "approved_at": args.approved_at, "run": args.run, "commit": args.sha, "notes": notes}

    findings.write_text(json.dumps(doc, indent=2), encoding="utf-8")

    print(f"stamped: approved by {args.approver}")





def section(plan, title):

    match = re.search(rf"(?ms)^## {re.escape(title)}\s*\n(.*?)(?=^## |\Z)", plan)

    return match.group(1) if match else ""





def validate_plan(args):

    doc = json.loads(pathlib.Path(args.findings).read_text(encoding="utf-8"))

    plan = pathlib.Path(args.plan).read_text(encoding="utf-8") if pathlib.Path(args.plan).exists() else ""

    findings = {f["id"]: f for f in doc["findings"]}

    to_assign = [i for i, f in findings.items() if f["rank"] != "No change"]

    checks = [("Plan file exists", bool(plan), args.plan)]



    headings = set(re.findall(r"(?m)^##\s+(.+?)\s*$", plan))

    missing_sections = [s for s in PLAN_SECTIONS if s not in headings]

    checks.append(("Required sections", not missing_sections, "all present" if not missing_sections else "missing: " + ", ".join(missing_sections)))



    params = re.search(r"## Run Parameters\s*\n+```ya?ml\n(.*?)```", plan, flags=re.S)

    block = params.group(1) if params else ""

    problems = []

    issue = re.search(r"(?m)^issue:\s*(\d+)\s*$", block)

    if not issue or int(issue.group(1)) != int(doc["issue"]):

        problems.append(f"issue must be {doc['issue']}")

    if not re.search(r"(?m)^project:\s*asset-manager\s*$", block):

        problems.append("project must be asset-manager")

    target = re.search(r"(?m)^target:.*$", block)

    target_line = target.group(0) if target else ""

    if not re.search(r"java:\s*21\b", target_line):

        problems.append("target java must be 21")

    boot = re.search(r'spring-boot:\s*"?(3\.5\.\d+)"?', target_line)

    if not boot:

        problems.append("target spring-boot must be an exact 3.5.x version")

    checks.append(("Run Parameters", not problems, f"issue {doc['issue']}, asset-manager, Java 21, Spring Boot {boot.group(1)}" if not problems else "; ".join(problems)))



    # Every finding that needs work is owned by exactly one execution step.

    steps = re.split(r"(?m)^### ", section(plan, "Execution Plan"))[1:]

    owners = {i: [s.splitlines()[0].strip() for s in steps if re.search(rf"\b{re.escape(i)}\b", s)] for i in to_assign}

    unowned = [i for i, s in owners.items() if not s]

    multiple = [f"{i} ({len(s)} steps)" for i, s in owners.items() if len(s) > 1]

    detail = f"{len(to_assign) - len(unowned) - len(multiple)} of {len(to_assign)} findings in exactly one step"

    if unowned:

        detail += f"; not in any step: {', '.join(unowned)}"

    if multiple:

        detail += f"; in several steps: {', '.join(multiple)}"

    checks.append(("Each finding owned by one step", bool(steps) and not unowned and not multiple, detail if steps else "no ### step subsections in Execution Plan"))



    # The coverage table has exactly one row per finding, with an allowed agent.

    rows = {}

    for line in section(plan, "Finding Coverage").splitlines():

        cells = [c.strip().strip("`") for c in line.strip().strip("|").split("|")]

        if line.lstrip().startswith("|") and cells and re.fullmatch(r"[CD]-\d{2}", cells[0]):

            rows.setdefault(cells[0], []).append(cells)

    missing_rows = [i for i in findings if i not in rows]

    duplicate_rows = [i for i, r in rows.items() if len(r) > 1]

    allowed = {"modernize-build-upgrader", "modernize-code-fixer", "none"}

    bad_agent = [i for i, r in rows.items() if not any(cell in allowed for cell in r[0][1:])]

    ok = not missing_rows and not duplicate_rows and not bad_agent

    detail = f"{len(rows)} of {len(findings)} findings have one row"

    for label, items in (("missing", missing_rows), ("duplicated", duplicate_rows), ("no allowed agent", bad_agent)):

        if items:

            detail += f"; {label}: {', '.join(items)}"

    checks.append(("Finding Coverage table", ok, detail))



    unknown = sorted(set(re.findall(r"\b[CD]-\d{2}\b", plan)) - set(findings))

    checks.append(("No invented finding IDs", not unknown, "none" if not unknown else ", ".join(unknown)))

    notes = (doc.get("approval") or {}).get("notes") or []

    if notes:

        answered = re.search(r"(?m)^### Reviewer notes\s*$", section(plan, "Assessment Summary"))

        checks.append(("Reviewer notes answered", bool(answered),

                       f"{P(len(notes), "reviewer note")} answered under Assessment Summary" if answered else f"{P(len(notes), "reviewer note")} from gate 1, but no `### Reviewer notes` subsection in Assessment Summary"))

    execution_lines = section(plan, "Execution Plan").lower().splitlines()

    negated = re.compile(r"\b(no|not|never|without|excluded?|out of scope)\b")

    words = ("dockerfile", "kubernetes", "service bus", "blob storage", "bicep", "terraform", "deploy")

    bad_scope = sorted({w for line in execution_lines if not negated.search(line) for w in words if w in line})

    checks.append(("No out-of-scope steps", not bad_scope, "no container, deployment or Azure migration steps" if not bad_scope else "mentions " + ", ".join(bad_scope)))



    passed = all(ok for _, ok, _ in checks)

    lines = ["<!-- modernize-plan-validation -->", "## Plan validation", "",

             f"Result: {'PASS' if passed else 'NEEDS ATTENTION'}. Deterministic checks of `{args.plan}` against `findings.json`. No AI.", "",

             "| Check | Result | Detail |", "|---|---|---|"]

    lines += [f"| {name} | {'pass' if ok else 'fail'} | {cell(detail)} |" for name, ok, detail in checks]

    pathlib.Path(args.out).write_text("\n".join(lines) + "\n", encoding="utf-8")

    print(f"plan validation: {'PASS' if passed else 'NEEDS ATTENTION'}")

    if args.github_output:

        with open(args.github_output, "a", encoding="utf-8") as handle:

            handle.write(f"result={'pass' if passed else 'fail'}\n")





def main():

    parser = argparse.ArgumentParser()

    sub = parser.add_subparsers(dest="command", required=True)

    b = sub.add_parser("build")

    b.add_argument("--issue", required=True)

    b.add_argument("--facts", required=True)

    b.add_argument("--out", required=True)

    b.add_argument("--usage")

    b.add_argument("--workflows", default=".github/workflows")

    a = sub.add_parser("approve")

    a.add_argument("--issue", required=True)

    e = sub.add_parser("expand-request")

    e.add_argument("--issue", required=True)

    e.add_argument("--project", default="asset-manager")

    s = sub.add_parser("stamp")

    s.add_argument("--report", required=True)

    s.add_argument("--findings", required=True)

    s.add_argument("--approver", required=True)

    s.add_argument("--approved-at", required=True)

    s.add_argument("--run", required=True)

    s.add_argument("--sha", required=True)

    s.add_argument("--notes", help="JSON list of reviewer comments: author, created_at, body")

    v = sub.add_parser("validate-plan")

    v.add_argument("--findings", required=True)

    v.add_argument("--plan", required=True)

    v.add_argument("--out", required=True)

    v.add_argument("--github-output")

    args = parser.parse_args()

    {"build": build, "approve": approve, "stamp": stamp, "validate-plan": validate_plan, "expand-request": expand_request}[args.command](args)





if __name__ == "__main__":

    main()

